"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["76234"],{66087(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_fase.prazo_segunda_instancia_nao_declarado","status":422,"titulo":"O recurso que admite inst\xe2ncia superior precisa declarar o prazo da 2\xaa inst\xe2ncia"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_fase.prazo_segunda_instancia_nao_declarado","requisitos":["UNI-REQ-0451"],"oQueAconteceu":["A configura\xe7\xe3o do recurso de uma fase admite inst\xe2ncia superior, mas n\xe3o declara o **prazo para recorrer em 2\xaa inst\xe2ncia**. Quando o recurso admite inst\xe2ncia superior, o prazo da 2\xaa inst\xe2ncia \xe9 obrigat\xf3rio, com as mesmas unidades e a mesma contagem do prazo de interposi\xe7\xe3o (UNI-REQ-0451). A recusa sai com **422**, nada \xe9 gravado, e o campo recusado \xe9 `fases[i].regraRecurso.prazoSegundaInstanciaValor`, em que `i` \xe9 a posi\xe7\xe3o da fase.","A mensagem da resposta diz: \\"O recurso admite inst\xe2ncia superior: informe o prazo para recorrer em 2\xaa inst\xe2ncia, com valor e unidade (dias \xfateis ou horas).\\""],"comoResolver":["Escolha uma das duas sa\xeddas, na mesma grava\xe7\xe3o:","- informe o prazo da 2\xaa inst\xe2ncia, com valor maior que zero (inteiro, quando a unidade for `DIAS_UTEIS`) e a unidade `DIAS_UTEIS` ou `HORAS`;\\n- ou retire a inst\xe2ncia superior: marque `admiteInstanciaSuperior` como falso e retire tamb\xe9m o valor e a unidade do prazo da 2\xaa inst\xe2ncia."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Leitura do documento de configura\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do recurso da fase"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);